dtsPropsFor.Badge:
/** Text shown inside the pill. */
  label: string;
  /** Visual tone. @default 'default' */
  variant?: 'default' | 'error' | 'success';

dtsPropsFor.EmptyState:
/** Primary line, e.g. "No traces yet". */
  message: string;
  /** Optional secondary line under the message. */
  description?: string;

dtsPropsFor.LastUpdated:
/** Epoch ms of the last successful fetch; derives "Updated <relative>" and self-ticks every 10s. */
  at?: number;
  /** Explicit label (e.g. "Synced 2m ago"); overrides the derived text and disables ticking. */
  label?: string;
  /** Freshness tone — drives dot color, the live-only glow, and text color. @default 'live' */
  tone?: 'live' | 'stale' | 'error' | 'syncing';

dtsPropsFor.Card:
/** Card body. */
  children: React.ReactNode;
  /** Extra inline styles merged onto the surface container. */
  style?: React.CSSProperties;
  /** Click handler; makes the whole card interactive. */
  onClick?: () => void;

dtsPropsFor.CardHeader:
/** Header title. */
  title: string;
  /** Optional muted subtitle under the title. */
  subtitle?: string;
  /** Optional node aligned to the right (actions, status). */
  right?: React.ReactNode;

dtsPropsFor.Sparkline:
/** Series values; `null` entries are gaps (line breaks, x-slot preserved). */
  data: (number | null)[];
  /** SVG width in px. @default 80 */
  width?: number;
  /** SVG height in px. @default 24 */
  height?: number;
  /** Stroke/fill color (any CSS color or var). @default 'var(--accent)' */
  color?: string;
  /** Area fill opacity under the line. @default 0.12 */
  fillOpacity?: number;

dtsPropsFor.StatusPill:
/** Status key: completed | failed | warning | healthy | critical | ok map to a color+label; any other value renders muted with the raw text. */
  status: string;
  /** Override the pill text; defaults to the mapped label. */
  children?: React.ReactNode;

dtsPropsFor.Icon:
/** SVG path `d` attribute for the 24x24 viewBox glyph. */
  d: string;
  /** Icon size in px. @default 16 */
  size?: number;
  /** Stroke width. @default 1.5 */
  stroke?: number;
  /** Extra inline styles on the <svg>. */
  style?: React.CSSProperties;

dtsPropsFor.CostBarChart:
/** Cost buckets over the query window. */
  series: { label: string; value: number }[];
  /** Chart height in px (width fills the container). @default 220 */
  height?: number;

dtsPropsFor.LatencyChart:
/** Latency percentile buckets; each percentile may be `null` for buckets with no runs (rendered as gaps). */
  series: { label: string; p50: number | null; p95: number | null; p99: number | null }[];
  /** Chart height in px (width fills the container). @default 220 */
  height?: number;

dtsPropsFor.HorizonStrip:
/** Per-bucket error counts; cell intensity scales with errors/total. */
  data: { label: string; errors: number; total: number }[];
  /** Strip height in px (width fills the container). @default 40 */
  height?: number;
